<?php
require __DIR__.'/layout_start.php';$id=(int)($_GET['id']??0);$product=['Nome_Prod'=>'','ID_Marca'=>'','ID_Categoria'=>'','Valor_Preco'=>'','ValorPromocional'=>'','QtdEstoque'=>'0','PesoKG'=>'','Slug'=>'','StatusProduto'=>'Disponível','Descricao'=>'','Especificacoes'=>'','GarantiaMeses'=>'','UrlImagem'=>''];
if($id){$q=db()->prepare('SELECT p.*,d.Descricao,d.Especificacoes,d.GarantiaMeses,(SELECT UrlImagem FROM tbl_ProdutoImagem pi WHERE pi.ID_Produto=p.ID_Produto ORDER BY Principal DESC,ID_Imagem ASC LIMIT 1) UrlImagem FROM tbl_Produtos p LEFT JOIN tbl_DescricaoProduto d ON d.ID_Produto=p.ID_Produto WHERE p.ID_Produto=?');$q->execute([$id]);$product=$q->fetch();if(!$product){flash('error','Produto não encontrado.');redirect('produtos.php');}$product['StatusProduto']=normalize_product_status((int)($product['QtdEstoque']??0),(string)($product['StatusProduto']??''));}
$brands=db()->query('SELECT * FROM tbl_Marca ORDER BY NomeMarca')->fetchAll();$categories=db()->query('SELECT * FROM tbl_Categoria ORDER BY NomeCategoria')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){try{$data=['nome'=>trim($_POST['nome']),'marca'=>(int)$_POST['marca'],'categoria'=>(int)$_POST['categoria'],'preco'=>(float)$_POST['preco'],'promo'=>$_POST['promocional']!==''?(float)$_POST['promocional']:null,'estoque'=>(int)$_POST['estoque'],'peso'=>(float)$_POST['peso'],'slug'=>trim($_POST['slug']),'status'=>$_POST['status'],'descricao'=>trim($_POST['descricao']),'especificacoes'=>trim($_POST['especificacoes']),'garantia'=>$_POST['garantia']!==''?(int)$_POST['garantia']:null,'imagem'=>trim($_POST['imagem'])];if($data['nome']===''||$data['preco']<=0||$data['peso']<=0)throw new Exception('Preencha os campos obrigatórios corretamente.');$data['status']=normalize_product_status($data['estoque'],$data['status']);db()->beginTransaction();if($id){db()->prepare('UPDATE tbl_Produtos SET Nome_Prod=?,ID_Marca=?,ID_Categoria=?,Valor_Preco=?,ValorPromocional=?,QtdEstoque=?,PesoKG=?,Slug=?,StatusProduto=? WHERE ID_Produto=?')->execute([$data['nome'],$data['marca'],$data['categoria'],$data['preco'],$data['promo'],$data['estoque'],$data['peso'],$data['slug'],$data['status'],$id]);}else{db()->prepare('INSERT INTO tbl_Produtos (Nome_Prod,ID_Marca,ID_Categoria,Valor_Preco,ValorPromocional,QtdEstoque,PesoKG,Slug,StatusProduto) VALUES (?,?,?,?,?,?,?,?,?)')->execute([$data['nome'],$data['marca'],$data['categoria'],$data['preco'],$data['promo'],$data['estoque'],$data['peso'],$data['slug'],$data['status']]);$id=(int)db()->lastInsertId();}db()->prepare('INSERT INTO tbl_DescricaoProduto (ID_Produto,Descricao,Especificacoes,GarantiaMeses) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE Descricao=VALUES(Descricao),Especificacoes=VALUES(Especificacoes),GarantiaMeses=VALUES(GarantiaMeses)')->execute([$id,$data['descricao'],$data['especificacoes'],$data['garantia']]);if($data['imagem']!==''){db()->prepare('DELETE FROM tbl_ProdutoImagem WHERE ID_Produto=?')->execute([$id]);db()->prepare('INSERT INTO tbl_ProdutoImagem (ID_Produto,UrlImagem,Principal) VALUES (?,?,1)')->execute([$id,$data['imagem']]);}db()->commit();flash('success','Produto salvo com sucesso.');redirect('produtos.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error',$e instanceof PDOException?'Dados inválidos.':$e->getMessage());$product=array_merge($product,['Nome_Prod'=>$_POST['nome']??'','ID_Marca'=>$_POST['marca']??'','ID_Categoria'=>$_POST['categoria']??'','Valor_Preco'=>$_POST['preco']??'','ValorPromocional'=>$_POST['promocional']??'','QtdEstoque'=>$_POST['estoque']??'','PesoKG'=>$_POST['peso']??'','Slug'=>$_POST['slug']??'','StatusProduto'=>$_POST['status']??'','Descricao'=>$_POST['descricao']??'','Especificacoes'=>$_POST['especificacoes']??'','GarantiaMeses'=>$_POST['garantia']??'','UrlImagem'=>$_POST['imagem']??'']);}}
?> <div class="admin-head"><div><div class="eyebrow">CATÁLOGO</div><h1><?= $id?'Editar produto.':'Novo produto.' ?></h1></div><a class="btn btn-outline" href="produtos.php">Voltar</a></div><form class="admin-form" method="post"><div class="form-group"><label>Nome do produto *</label><input name="nome" required value="<?= e($product['Nome_Prod']) ?>"></div><div class="form-group"><label>Slug (opcional)</label><input name="slug" value="<?= e($product['Slug']) ?>"></div><div class="form-row"><div class="form-group"><label>Marca *</label><select name="marca" required><?php foreach($brands as $b): ?><option value="<?= $b['ID_Marca'] ?>" <?= $product['ID_Marca']==$b['ID_Marca']?'selected':'' ?>><?= e($b['NomeMarca']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Categoria *</label><select name="categoria" required><?php foreach($categories as $c): ?><option value="<?= $c['ID_Categoria'] ?>" <?= $product['ID_Categoria']==$c['ID_Categoria']?'selected':'' ?>><?= e($c['NomeCategoria']) ?></option><?php endforeach; ?></select></div></div><div class="form-row"><div class="form-group"><label>Preço normal *</label><input type="number" name="preco" step="0.01" min="0.01" required value="<?= e((string)$product['Valor_Preco']) ?>"></div><div class="form-group"><label>Preço promocional</label><input type="number" name="promocional" step="0.01" min="0" value="<?= e((string)$product['ValorPromocional']) ?>"></div></div><div class="form-row"><div class="form-group"><label>Estoque *</label><input type="number" name="estoque" min="0" required value="<?= e((string)$product['QtdEstoque']) ?>"></div><div class="form-group"><label>Peso (kg) *</label><input type="number" name="peso" step="0.01" min="0.01" required value="<?= e((string)$product['PesoKG']) ?>"></div></div><div class="form-group"><label>Status</label><select name="status"><option <?= $product['StatusProduto']==='Disponível'?'selected':'' ?>>Disponível</option><option <?= $product['StatusProduto']==='Esgotado'?'selected':'' ?>>Esgotado</option></select></div><div class="form-group"><label>URL da imagem principal</label><input name="imagem" type="url" value="<?= e($product['UrlImagem']) ?>" placeholder="https://..."></div><div class="form-group"><label>Descrição</label><textarea name="descricao"><?= e($product['Descricao']) ?></textarea></div><div class="form-group"><label>Especificações</label><textarea name="especificacoes" placeholder="CPU: ...&#10;GPU: ...&#10;Memória: ..."><?= e($product['Especificacoes']) ?></textarea></div><div class="form-group"><label>Garantia (meses)</label><input name="garantia" type="number" min="0" value="<?= e((string)$product['GarantiaMeses']) ?>"></div><button class="btn btn-primary" type="submit">Salvar produto →</button></form><?php require __DIR__.'/layout_end.php'; ?>
